#!/usr/bin/env python3
"""Re-runnable verification of the FixFirst knowledge-base candidates (candidates.toml and, when present,
candidates-optional.toml in the same directory).

Every candidate entry says "from version X on, name N is gone from distribution D". This script proves it
by running real code, never by reading documentation:

  * a CHECK runs one snippet (`python -I -B`, empty working directory) in the last release that still has the
    name (it must succeed), in the first release without it (it must raise the expected error) and in newer
    releases (it must still raise). The exact versions and the exact error text are printed. For third-party
    packages the two pinned releases must be adjacent on PyPI, so "first release" is proven, not assumed.
  * the error message is mapped to the knowledge key the same way fixfirst/evidence.py does, so an entry
    whose shape could not be matched by a real error is rejected.
  * a SUPPORTING PROBE asserts a claim made in a replacement text (for example that two APIs are equivalent).
  * the candidate files are validated against the rules of fixfirst/domain.py (kinds, required keys, source ids,
    key collisions with domain.toml), every key must be covered by a passing check, and usage patterns must
    occur in the observed message.
  * the existing standard-library entries of domain.toml are audited the same way (--domain).
  * with --fixfirst-src the candidates are merged into a COPY of the knowledge base, loaded by the real
    loader, and every entry is run through the real rule engine (rules D01-D07, P10).

Requirements: Python >= 3.11 to run this file, `uv` on PATH, uv-managed CPython 3.8 to 3.14 (uv python install
3.8 3.9 3.10 3.11 3.12 3.13 3.14; 3.15 is used for forward-looking probes if present) and network access to PyPI.
Throwaway virtual environments live in the system temp directory and are deleted at the end.

    python verify.py --domain /path/to/domain.toml --fixfirst-src /path/to/repo/src > verification-log.txt

Exit status 0 means: every check and probe passed, 0 cross-check problems, 0 unexpected audit failures.
"""

from __future__ import annotations

import argparse
import datetime
import tomllib


import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import time
import urllib.request
from dataclasses import dataclass, field

UV = shutil.which("uv") or "uv"
MARK = "@@PROBE@@"

RUNNER = r'''
import sys, json, warnings, io, contextlib
spec = json.load(sys.stdin)
scrub_pairs = spec["scrub"]
def scrub(s):
    for a, b in scrub_pairs:
        if a:
            s = s.replace(a, b)
    return s
results = {}
for item in spec["items"]:
    rec = {"ok": True}
    out = io.StringIO()
    with warnings.catch_warnings(record=True) as caught, contextlib.redirect_stdout(out):
        warnings.simplefilter("always")
        warnings.simplefilter("ignore", ResourceWarning)     # noise from unclosed files in snippets
        try:
            exec(compile(item["code"], "<probe:%s>" % item["id"], "exec"), {"__name__": "__probe__"})
        except BaseException as e:
            rec.update(ok=False, exc_type=type(e).__name__, exc_msg=scrub(str(e)))
    rec["warnings"] = [{"category": w.category.__name__, "message": scrub(str(w.message))} for w in caught]
    rec["stdout"] = scrub(out.getvalue())[:1500]
    results[item["id"]] = rec
versions = {}
for name in spec["dists"]:
    try:
        from importlib.metadata import version
        versions[name] = version(name)
    except Exception:
        versions[name] = None
print(spec["mark"] + json.dumps({"python": sys.version.split()[0], "impl": sys.implementation.name,
                                  "dists": versions, "results": results}))
'''


def canon(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name).lower()


@dataclass(frozen=True)
class Env:
    python: str                      # minor version, e.g. "3.12"
    pkgs: tuple = ()                 # pip requirement strings; () = bare interpreter
    only_binary: bool = True         # refuse source builds (fast, reproducible)

    def label(self) -> str:
        return f"py{self.python}" + ("".join(" " + p for p in self.pkgs) if self.pkgs else "")


def E(python: str, *pkgs: str, only_binary: bool = True) -> Env:
    return Env(python, tuple(pkgs), only_binary)


@dataclass
class Check:
    id: str
    dist: str                         # "python" or a distribution name
    first_gone: str                   # first release in which the name is gone ("3.12", "2.0")
    covers: tuple                     # index keys of the candidate entries this check supports
    before: Env
    after: Env
    code: str
    expect: str = "AttributeError"    # exception type name(s) after, "A|B"
    match: str = ""                   # substring that must appear in the message after
    later: tuple = ()                 # further Envs where the snippet must still raise
    note: str = ""
    kind: str = "removed"             # "removed" | "deprecated"
    warn: str = ""                    # deprecated: regex the warning in `after` must match
    warn_category: str = "DeprecationWarning"
    isolate: bool = True              # each snippet runs in its own process (no shared interpreter state)
    adjacent: bool = True             # verify via PyPI that before is the immediate predecessor
    dists: tuple = ()                 # distributions whose installed version is reported
    shape: bool = True                # verify covers keys are derivable from the observed message
    shape_role: str = "after"          # which record the keys are derived from ("later0" if `after` words it differently)
    group: str = ""                   # section header in the log
    finding: bool = False             # audit only: a failing result is a FINDING (the knowledge base claim is contradicted)

    def __post_init__(self):
        if isinstance(self.covers, str):
            self.covers = (self.covers,)
        self.later = tuple(self.later)


# ---------------------------------------------------------------------------------------
# interpreters and environments
# ---------------------------------------------------------------------------------------

_PYTHONS: dict = {}


def find_pythons() -> dict:
    if _PYTHONS:
        return _PYTHONS
    out = subprocess.run([UV, "python", "list", "--only-installed", "--output-format", "json"],
                         capture_output=True, text=True, check=True).stdout
    best = {}
    for d in json.loads(out):
        if d.get("implementation") != "cpython" or d.get("variant") != "default":
            continue
        parts = d["version_parts"]
        mm = f"{parts['major']}.{parts['minor']}"
        key = (parts["major"], parts["minor"], parts["patch"])
        if mm not in best or key > best[mm][0]:
            best[mm] = (key, d["path"])
    _PYTHONS.update({mm: p for mm, (_, p) in best.items()})
    return _PYTHONS


class Workspace:
    def __init__(self, base: str | None = None, keep: bool = False):
        self.base = base or tempfile.mkdtemp(prefix="ffk-verify-")
        self.keep = keep
        self.neutral = os.path.join(self.base, "neutral")
        os.makedirs(self.neutral, exist_ok=True)
        self.envs: dict = {}
        self.install_log: list = []
        self.scrub = None
        self._scrub_cache = {}
        self.cache = os.path.join(self.base, "uv-cache")
        self.env_vars = {k: v for k, v in os.environ.items() if not k.startswith("PYTHON")}
        self.env_vars["UV_CACHE_DIR"] = os.environ.get("UV_CACHE_DIR", self.cache)
        self.env_vars["VIRTUAL_ENV"] = ""
        self.env_vars.pop("VIRTUAL_ENV", None)
        self.env_vars["UV_NO_CONFIG"] = "1"

    def close(self):
        if not self.keep:
            shutil.rmtree(self.base, ignore_errors=True)

    # -- environments
    def python_for(self, env: Env) -> str:
        if env.python not in find_pythons():
            raise MissingInterpreter(f"interpreter {env.python} is not installed (uv python install {env.python})")
        if not env.pkgs:
            return find_pythons()[env.python]
        if env in self.envs:
            return self.envs[env]
        h = hashlib.sha1(repr((env.python, env.pkgs, env.only_binary)).encode()).hexdigest()[:10]
        d = os.path.join(self.base, f"env-{env.python}-{h}")
        py = os.path.join(d, "bin", "python")
        subprocess.run([UV, "venv", "--quiet", "--python", find_pythons()[env.python], d],
                       check=True, capture_output=True, text=True, env=self.env_vars)
        cmd = [UV, "pip", "install", "--quiet", "--python", py]
        if env.only_binary:
            cmd += ["--only-binary", ":all:"]
        cmd += list(env.pkgs)
        t0 = time.time()
        r = subprocess.run(cmd, capture_output=True, text=True, env=self.env_vars)
        self.install_log.append((env, r.returncode, round(time.time() - t0, 1), (r.stderr or r.stdout)[-1500:]))
        if r.returncode != 0:
            raise EnvError(f"cannot install {env.label()}: {(r.stderr or r.stdout)[-800:]}")
        self.envs[env] = py
        return py

    def scrub_pairs(self, py: str) -> list:
        if py in self._scrub_cache:
            return self._scrub_cache[py]
        pairs = self._scrub_pairs(py)
        self._scrub_cache[py] = pairs
        return pairs

    def _scrub_pairs(self, py: str) -> list:
        pairs = []
        for p in {os.path.dirname(os.path.dirname(py)), os.path.realpath(os.path.dirname(os.path.dirname(py)))}:
            pairs.append([p, "<venv>" if self.base in p else "<python>"])
        base_prefix = subprocess.run([py, "-I", "-c", "import sys,os;print(sys.base_prefix);print(os.path.realpath(sys.base_prefix))"],
                                     capture_output=True, text=True).stdout.split()
        for p in base_prefix:
            pairs.append([p, "<python>"])
        pairs += [[self.base, "<tmp>"], [os.path.realpath(self.base), "<tmp>"],
                  [os.path.expanduser("~"), "<home>"]]
        return sorted(pairs, key=lambda x: -len(x[0]))

    # -- probes
    def probe(self, env: Env, items: list, dists=()) -> dict:
        """items: [(id, code)] -> {"python":..., "dists":..., "results": {id: record}}"""
        py = self.python_for(env)
        spec = {"mark": MARK, "scrub": self.scrub_pairs(py), "dists": sorted(set(dists)),
                "items": [{"id": i, "code": c} for i, c in items]}
        r = subprocess.run([py, "-I", "-B", "-c", RUNNER], input=json.dumps(spec), capture_output=True,
                           text=True, cwd=self.neutral, env=self.env_vars, timeout=900)
        for line in reversed(r.stdout.splitlines()):
            if line.startswith(MARK):
                return json.loads(line[len(MARK):])
        raise EnvError(f"probe crashed in {env.label()} (rc={r.returncode}): {(r.stderr or r.stdout)[-600:]}")


class EnvError(RuntimeError):
    pass


class MissingInterpreter(EnvError):
    pass


# ---------------------------------------------------------------------------------------
# PyPI release adjacency
# ---------------------------------------------------------------------------------------

_PYPI: dict = {}
_PYPI_YANKED: dict = {}


def pypi_versions(dist: str) -> list:
    """All release numbers (plain dotted numbers) that have files on PyPI, yanked ones included:
    a yanked release is still a release somebody may have installed, so it counts as 'first gone'."""
    dist = canon(dist)
    if dist not in _PYPI:
        with urllib.request.urlopen(f"https://pypi.org/pypi/{dist}/json", timeout=60) as r:
            data = json.load(r)
        stable, yanked = [], set()
        for v, files in data["releases"].items():
            if re.fullmatch(r"\d+(\.\d+)*", v) and files:
                stable.append(v)
                if all(f.get("yanked") for f in files):
                    yanked.add(v)
        _PYPI[dist] = sorted(stable, key=lambda v: tuple(int(x) for x in v.split(".")))
        _PYPI_YANKED[dist] = yanked
    return _PYPI[dist]


def pinned_version(env: Env, dist: str):
    for p in env.pkgs:
        m = re.fullmatch(r"([A-Za-z0-9_.\-]+)==([0-9][0-9.]*)", p.strip())
        if m and canon(m[1]) == canon(dist):
            return m[2]
    return None


def adjacency(dist: str, before: str, after: str) -> tuple[bool, str]:
    vs = pypi_versions(dist)
    vkey = lambda v: tuple(int(x) for x in v.split("."))
    below = [v for v in vs if vkey(v) < vkey(after)]
    if after not in vs:
        return False, f"{dist} {after} is not a release on PyPI"
    expected = below[-1] if below else None
    if expected != before:
        return False, f"immediate predecessor of {dist} {after} on PyPI is {expected}, not {before}"
    note = ""
    yanked = _PYPI_YANKED.get(canon(dist), set())
    if after in yanked or before in yanked:
        note = f" ({', '.join(v for v in (before, after) if v in yanked)} yanked on PyPI; yanked releases still count)"
    return True, f"{dist} {before} is the immediate predecessor of {after} on PyPI" + note


# ---------------------------------------------------------------------------------------
# message -> knowledge key (copies of the extraction regexes in fixfirst/evidence.py)
# ---------------------------------------------------------------------------------------

_MODULE_MISSING = re.compile(r"No module named '([\w.]+)'")
_CANNOT_IMPORT = re.compile(r"cannot import name '(\w+)' from (?:partially initialized module )?'([\w.]+)'")
_MODULE_ATTR = re.compile(r"module '([\w.]+)' has no attribute '(\w+)'")
_OBJECT_ATTR = re.compile(r"'([\w.]+)' object has no attribute '(\w+)'")
_KWARG = re.compile(r"(?:([\w.]+)\(\) )?got an unexpected keyword argument '(\w+)'")
_NUMPY_REMOVED = re.compile(r"`(?:np|numpy)\.(\w+)` was removed")
_DEPRECATED_NAME = re.compile(
    r"^(Attribute )?['\"`]?([A-Za-z_][\w.]*?)(?:\(\))?['\"`]? (?:is|are|has been|was) deprecated")


_IMPORT_STATEMENT = re.compile(r"^(?:from ([\w.]+) import ([\w, ()]+)|import ([\w.]+))")


def derive_keys(message: str, statement: str = "", exc_type: str = "") -> set:
    """The index keys FixFirst builds from an error message and the failing source line."""
    keys = set()
    if statement and exc_type.endswith(("ImportError", "ModuleNotFoundError")) and not _CANNOT_IMPORT.search(message):
        m = _IMPORT_STATEMENT.match(statement.strip())
        if m and m[1]:
            for name in re.findall(r"\w+", m[2]):
                keys.add(f"api:{m[1]}.{name}")
    m = _MODULE_MISSING.search(message)
    if m:
        keys.add("module:" + m[1])
    for name, module in _CANNOT_IMPORT.findall(message):
        keys.add(f"api:{module}.{name}")
    for module, name in _MODULE_ATTR.findall(message):
        keys.add(f"api:{module}.{name}")
    for owner, name in _OBJECT_ATTR.findall(message):
        keys.add("attribute:" + name)
        if owner != "NoneType" and "." not in owner:
            keys.add(f"api:{owner}.{name}")
    for owner, name in _KWARG.findall(message):
        keys.add("kwarg:" + name)
        owner = owner.split(".")[0] if owner else ""
        if owner:
            keys.add(f"kwarg:{owner}.{name}")
    for name in _NUMPY_REMOVED.findall(message):
        keys.add(f"api:numpy.{name}")
    return keys


def deprecated_key(message: str):
    m = _DEPRECATED_NAME.match(message)
    if not m:
        return None
    return ("attribute:" if m[1] else "api:") + m[2]


# ---------------------------------------------------------------------------------------
# running checks
# ---------------------------------------------------------------------------------------

def fmt_rec(rec: dict, limit: int = 330) -> str:
    if rec["ok"]:
        s = "OK"
    else:
        msg = " ".join(rec["exc_msg"].split())
        s = f"{rec['exc_type']}: {msg}"
    if len(s) > limit:
        s = s[: limit - 3] + "..."
    return s


def fmt_warnings(rec: dict, limit: int = 300) -> list:
    out = []
    for w in rec.get("warnings", []):
        msg = " ".join(w["message"].split())
        out.append(f"{w['category']}: {msg[:limit]}")
    return out


def run_checks(ws: Workspace, checks: list, progress=print) -> list:
    """Run every check; returns a list of result dicts (one per check)."""
    # one job = one interpreter process; isolated snippets get a job each, the others share one per environment
    plan: dict = {}
    for c in checks:
        for role, env in (("before", c.before), ("after", c.after), *[(f"later{i}", e) for i, e in enumerate(c.later)]):
            plan.setdefault((env, c.isolate), []).append((c, role))
    probed: dict = {}
    env_info: dict = {}
    jobs = []                     # (env, [(c, role)], dists)
    broken: dict = {}
    for (env, isolate), entries in plan.items():
        dists = set()
        for c, _ in entries:
            dists.update(c.dists)
            dists.update(re.split(r"[=<>!~ ]", p)[0] for p in env.pkgs)
        try:                      # create the environment first (sequentially: uv installs share a cache)
            ws.python_for(env)
        except EnvError as e:
            broken[env] = str(e)
            for c, role in entries:
                probed[(c.id, role)] = {"ok": None, "error": str(e), "warnings": []}
            progress(f"  ENV ERROR {env.label()}: {str(e)[:200]}")
            continue
        if isolate:
            jobs += [(env, [(c, role)], dists) for c, role in entries]
        else:
            jobs.append((env, entries, dists))

    def do(job):
        env, entries, dists = job
        res = ws.probe(env, [(f"{c.id}|{role}", c.code) for c, role in entries], dists)
        return env, entries, res

    workers = max(1, int(os.environ.get("FFK_JOBS", "6")))
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = [(job, ex.submit(do, job)) for job in jobs]
        for job, fut in futures:
            env, entries, _ = job
            try:
                _, _, res = fut.result()
            except EnvError as e:
                for c, role in entries:
                    probed[(c.id, role)] = {"ok": None, "error": str(e), "warnings": []}
                progress(f"  PROBE ERROR {env.label()}: {str(e)[:200]}")
                continue
            env_info[env] = {"python": res["python"], "dists": res["dists"]}
            for c, role in entries:
                probed[(c.id, role)] = res["results"][f"{c.id}|{role}"]
    results = []
    for c in checks:
        r = {"check": c, "problems": [], "info": {}}
        recs = {"before": probed[(c.id, "before")], "after": probed[(c.id, "after")]}
        for i in range(len(c.later)):
            recs[f"later{i}"] = probed[(c.id, f"later{i}")]
        r["recs"] = recs
        for role, rec in recs.items():
            if rec.get("ok") is None:
                r["problems"].append(f"{role}: environment error")
        if not r["problems"]:
            b, a = recs["before"], recs["after"]
            if c.kind == "removed":
                if not b["ok"]:
                    r["problems"].append(f"before: expected the snippet to succeed, got {fmt_rec(b)}")
                exp = c.expect.split("|")
                for role in [k for k in recs if k != "before"]:
                    rec = recs[role]
                    if rec["ok"]:
                        r["problems"].append(f"{role}: expected {c.expect}, but the snippet succeeded")
                    elif rec["exc_type"] not in exp:
                        r["problems"].append(f"{role}: expected {c.expect}, got {rec['exc_type']}: {rec['exc_msg'][:120]}")
                    elif c.match and c.match not in rec["exc_msg"]:
                        r["problems"].append(f"{role}: message lacks {c.match!r}: {rec['exc_msg'][:120]}")
                a = recs[c.shape_role]
                if c.shape and not a["ok"] and not r["problems"]:
                    last_line = [ln for ln in c.code.splitlines() if ln.strip()][-1]
                    derived = derive_keys(a["exc_msg"], last_line, a["exc_type"])
                    missing = [k for k in c.covers if not k.startswith("usage:") and k not in derived]
                    r["info"]["derived"] = sorted(derived)
                    r["info"]["derived_from"] = c.shape_role
                    if missing:
                        r["problems"].append(f"keys {missing} cannot be derived from the message (FixFirst would derive {sorted(derived)})")
            else:  # deprecated: still works after, but warns; did not warn before
                pat = re.compile(c.warn)
                for role, rec in recs.items():
                    if not rec["ok"]:
                        r["problems"].append(f"{role}: deprecated name must still work, got {fmt_rec(rec)}")
                        continue
                    hit = [w for w in rec["warnings"] if w["category"] == c.warn_category and pat.search(w["message"])]
                    if role == "before" and hit:
                        r["problems"].append(f"before: already warns: {hit[0]['message'][:120]}")
                    if role != "before" and not hit:
                        r["problems"].append(f"{role}: no {c.warn_category} matching /{c.warn}/")
                    if role == "after" and hit and c.shape:
                        got = deprecated_key(hit[0]["message"])
                        r["info"]["derived"] = [got]
                        if got not in c.covers:
                            r["problems"].append(f"warning text yields key {got!r}, not {list(c.covers)}")
        # adjacency of pinned releases
        if c.adjacent and c.dist != "python":
            bv, av = pinned_version(c.before, c.dist), pinned_version(c.after, c.dist)
            if bv and av:
                try:
                    ok, why = adjacency(c.dist, bv, av)
                except Exception as e:  # network trouble must not hide a result
                    ok, why = False, f"adjacency lookup failed: {e}"
                r["info"]["adjacent"] = why
                if not ok:
                    r["problems"].append(why)
            else:
                r["problems"].append(f"{c.dist} is not pinned with == in both before and after")
        r["envs"] = {role: env_info.get(env) for role, env in
                     (("before", c.before), ("after", c.after), *[(f"later{i}", e) for i, e in enumerate(c.later)])}
        results.append(r)
    return results


def _norm_msg(msg):
    """Compare messages ignoring the interpreter minor version inside file paths."""
    return re.sub(r"python3\.\d+", "pythonX", msg) if isinstance(msg, str) else msg


def format_result(r: dict) -> str:
    c: Check = r["check"]
    status = "PASS" if not r["problems"] else ("FINDING" if c.finding else "FAIL")
    if c.finding and not r["problems"]:
        status = "FAIL"
    lines = [f"[{status}] {c.id}  ({c.dist} {c.first_gone}, {c.kind})",
             f"    covers : {', '.join(c.covers)}",
             f"    probe  : {c.code.strip().replace(chr(10), '; ')[:240]}"]
    after_rec = r["recs"].get("after")
    later_same = []
    for role, rec in r["recs"].items():
        info = r["envs"].get(role) or {}
        ver = info.get("python", "?")
        dv = {k: v for k, v in (info.get("dists") or {}).items() if v}
        dtxt = " " + " ".join(f"{k} {v}" for k, v in sorted(dv.items())) if dv else ""
        if role.startswith("later") and after_rec and rec.get("ok") is not None and (
                rec.get("ok"), rec.get("exc_type"), _norm_msg(rec.get("exc_msg"))) == (
                after_rec.get("ok"), after_rec.get("exc_type"), _norm_msg(after_rec.get("exc_msg"))) and not r["problems"]:
            later_same.append(f"{ver}{dtxt}")
            continue
        lines.append(f"    {role:7s}: python {ver}{dtxt}: {fmt_rec(rec) if rec.get('ok') is not None else rec.get('error')}")
        if role == "before" or c.kind == "deprecated":
            for w in fmt_warnings(rec)[:2]:
                lines.append(f"             warning: {w}")
    if later_same:
        lines.append(f"    later  : python {', '.join(later_same)}: same result as after")
    if c.kind == "deprecated":
        pass
    if r["info"].get("derived"):
        lines.append(f"    keys   : FixFirst derives {', '.join(r['info']['derived'])} from the '{r['info'].get('derived_from', 'after')}' message")
    if r["info"].get("adjacent"):
        lines.append(f"    release: {r['info']['adjacent']}")
    if c.note:
        lines.append(f"    note   : {c.note}")
    for p in r["problems"]:
        lines.append(f"    PROBLEM: {p}")
    return "\n".join(lines)


# ---------------------------------------------------------------------------------------
# candidate file validation (mirrors fixfirst/domain.py: KINDS, required keys, source ids)
# ---------------------------------------------------------------------------------------

KINDS = {"module", "api", "attribute", "kwarg", "usage", "fixture"}
VERSION_RE = re.compile(r"^\d+(\.\d+)*$")
IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
DOTTED_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$")


def index_key(entry: dict, name: str) -> str:
    """The key under which fixfirst.domain.load() indexes a removed/deprecated name."""
    if entry.get("_table") == "deprecated":
        return f"api:{entry['module']}.{name}"
    return f"api:{entry['module']}.{name}" if entry["kind"] == "api" else f"{entry['kind']}:{name}"


def candidate_entries(data: dict) -> list:
    rows = []
    for table in ("removed", "deprecated", "unmaintained"):
        for i, e in enumerate(data.get(table, [])):
            rows.append({**e, "_table": table, "_n": i})
    return rows


def candidate_keys(data: dict) -> dict:
    """{index key: entry} for [[removed]] and [[deprecated]] entries (as the loader builds them)."""
    out = {}
    for e in candidate_entries(data):
        if e["_table"] == "unmaintained":
            out["unmaintained:" + canon(e["distribution"])] = e
            continue
        for name in e["names"]:
            out[("deprecated:" if e["_table"] == "deprecated" else "removed:") + index_key(e, name)] = e
    return out


def validate_candidates(cand: dict, domain: dict) -> list:
    """Return a list of problems (empty = valid). Rules mirror domain.load() plus style rules."""
    problems = []
    dom_sources = domain.get("sources", {})
    cand_sources = cand.get("sources", {})
    for sid, s in cand_sources.items():
        if sid in dom_sources:
            problems.append(f"source id {sid!r} is already defined in domain.toml (do not redefine; reference it)")
        for k in ("title", "url"):
            if not isinstance(s.get(k), str) or not s[k].strip():
                problems.append(f"source {sid!r}: missing {k}")
        if isinstance(s.get("url"), str) and not s["url"].startswith("https://"):
            problems.append(f"source {sid!r}: url must be https")
    allowed_tables = {"removed", "deprecated", "unmaintained", "sources"}
    for t in cand:
        if t not in allowed_tables:
            problems.append(f"unexpected top-level table {t!r}")
    # existing keys
    dom_removed, dom_deprecated = {}, {}
    for e in domain.get("removed", []):
        for name in e["names"]:
            dom_removed["api:" + e["module"] + "." + name if e["kind"] == "api" else f"{e['kind']}:{name}"] = e
    for e in domain.get("deprecated", []):
        for name in e["names"]:
            dom_deprecated[f"api:{e['module']}.{name}"] = e
    dom_unmaintained = {canon(e["distribution"]) for e in domain.get("unmaintained", [])}
    seen = {}
    for e in candidate_entries(cand):
        tag = f"[[{e['_table']}]] #{e['_n'] + 1} {e.get('names', e.get('distribution'))}"
        required = {"removed": ("kind", "names", "distribution", "version", "replacement", "source"),
                    "deprecated": ("module", "names", "distribution", "version", "replacement", "source"),
                    "unmaintained": ("distribution", "last", "replacement", "source")}[e["_table"]]
        for k in required:
            if k not in e or e[k] in ("", None, []):
                problems.append(f"{tag}: missing required key {k!r}")
        if any(k not in e for k in required):
            continue
        if e["source"] not in dom_sources and e["source"] not in cand_sources:
            problems.append(f"{tag}: source {e['source']!r} is not defined in domain.toml or in this file")
        if "\n" in e["replacement"] or len(e["replacement"]) > 1100:
            problems.append(f"{tag}: replacement must be a single line of at most 1100 characters ({len(e['replacement'])})")
        if re.match(r"^(use|replace|change|switch|migrate)\b", e["replacement"], re.I):
            problems.append(f"{tag}: replacement starts with a verb; the UI already says 'Change the code to use ...'")
        if e["_table"] == "unmaintained":
            if canon(e["distribution"]) in dom_unmaintained:
                problems.append(f"{tag}: distribution already has an [[unmaintained]] entry")
            if not VERSION_RE.match(e["last"]):
                problems.append(f"{tag}: last must be a version string")
            continue
        if not VERSION_RE.match(e["version"]):
            problems.append(f"{tag}: version {e['version']!r} is not a dotted number")
        if e["_table"] == "removed":
            if e["kind"] not in KINDS:
                problems.append(f"{tag}: kind {e['kind']!r} not in {sorted(KINDS)}")
            if e["kind"] == "api" and not e.get("module"):
                problems.append(f"{tag}: kind=api needs module")
            if e["kind"] == "kwarg" and not e.get("callables"):
                problems.append(f"{tag}: kind=kwarg needs callables (rule D04 matches the resolved callee)")
            if e["kind"] == "usage" and not e.get("pattern"):
                problems.append(f"{tag}: kind=usage needs pattern")
            if e["kind"] == "fixture":
                problems.append(f"{tag}: fixture entries are out of scope for this batch")
        if len(set(e["names"])) != len(e["names"]):
            problems.append(f"{tag}: duplicate names inside the entry")
        for name in e["names"]:
            if e["_table"] == "deprecated" or e["kind"] in ("api", "kwarg", "attribute"):
                if not DOTTED_RE.match(name):
                    problems.append(f"{tag}: name {name!r} is not an identifier or dotted name")
            elif e["kind"] == "module" and not DOTTED_RE.match(name):
                problems.append(f"{tag}: module name {name!r} is not dotted identifiers")
            key = index_key(e, name)
            if e["_table"] == "removed":
                if key in dom_removed:
                    problems.append(f"{tag}: key {key} is already defined in domain.toml [[removed]]")
            else:
                if key in dom_deprecated:
                    problems.append(f"{tag}: key {key} is already defined in domain.toml [[deprecated]]")
            full = ("D:" if e["_table"] == "deprecated" else "R:") + key
            if full in seen:
                problems.append(f"{tag}: key {key} duplicates {seen[full]}")
            seen[full] = tag
    return problems


def coverage_problems(cand: dict, results: list, supports: list = ()) -> list:
    """Every removed/deprecated candidate key needs a passing check with matching dist and version;
    usage patterns must occur in the observed message; [[unmaintained]] entries need a passing
    support probe that pins the newest PyPI release."""
    passing = {}
    for r in results:
        if r["problems"]:
            continue
        c = r["check"]
        for key in c.covers:
            passing.setdefault(key, []).append(r)
    problems = []
    ok_support = [r for r in supports if not r["problems"]]
    for e in candidate_entries(cand):
        if e["_table"] == "unmaintained":
            hits = [r for r in ok_support if r["support"].pypi_latest == (e["distribution"], e["last"])]
            crash = [r for r in ok_support if r["support"].pypi_latest == () and r["support"].expect
                     and r["support"].env.pkgs and any(canon(p.split("==")[0]) == canon(e["distribution"]) for p in r["support"].env.pkgs)]
            if not hits:
                problems.append(f"unmaintained {e['distribution']} {e['last']}: no passing support pins the newest PyPI release")
            if not (crash or [r for r in hits if r["support"].expect]):
                problems.append(f"unmaintained {e['distribution']}: no passing support shows the crash")
            continue
        for name in e["names"]:
            key = index_key(e, name)
            hits = [r for r in passing.get(key, []) if canon(r["check"].dist) == canon(e["distribution"])
                    and r["check"].first_gone == e["version"]
                    and r["check"].kind == ("deprecated" if e["_table"] == "deprecated" else "removed")]
            if e["_table"] == "removed" and e["kind"] == "usage":
                pat = e.get("pattern", "")
                hits = [r for r in hits if r["recs"]["after"].get("exc_msg") and pat in r["recs"]["after"]["exc_msg"]]
                if not hits:
                    problems.append(f"usage {key}: pattern {pat!r} does not occur in the message of any passing check")
                continue
            if not hits:
                problems.append(f"{e['_table']} key {key} ({e['distribution']} {e['version']}) has no passing check")
    return problems


# ---------------------------------------------------------------------------------------
# supporting evidence for replacement text: snippets that must succeed (assert inside) in an env
# ---------------------------------------------------------------------------------------

@dataclass
class Support:
    id: str
    env: Env
    code: str
    claim: str                         # what the replacement text asserts, in words
    covers: tuple = ()                 # candidate keys whose replacement text this supports
    expect: str = ""                   # "" = snippet must succeed; else exception type it must raise
    match: str = ""
    pypi_latest: tuple = ()            # ("dist", "version"): the newest PyPI release must be exactly this
    group: str = ""                    # section header in the log


def run_supports(ws: Workspace, supports: list) -> list:
    out = []
    for sp in supports:
        try:
            res = ws.probe(sp.env, [(sp.id, sp.code)], [])
            rec = res["results"][sp.id]
            python = res["python"]
        except MissingInterpreter as e:
            # an interpreter that is not installed means the claim was NOT checked: never count that as a pass
            out.append({"support": sp, "problems": [f"NOT CHECKED: {e}"], "rec": {"ok": None, "warnings": [], "stdout": ""},
                        "python": "?", "not_checked": str(e)})
            continue
        except EnvError as e:
            out.append({"support": sp, "problems": [str(e)], "rec": {"ok": None, "warnings": []}, "python": "?"})
            continue
        problems = []
        if sp.pypi_latest:
            try:
                latest = pypi_versions(sp.pypi_latest[0])[-1]
            except Exception as e:
                latest = f"lookup failed: {e}"
            if latest != sp.pypi_latest[1]:
                problems.append(f"newest PyPI release of {sp.pypi_latest[0]} is {latest}, expected {sp.pypi_latest[1]}")
            else:
                rec.setdefault("stdout", "")
                rec["stdout"] = (rec["stdout"] or "") + f"\nPyPI newest release of {sp.pypi_latest[0]}: {latest}"
        if sp.expect:
            if rec["ok"] or rec["exc_type"] != sp.expect or (sp.match and sp.match not in rec["exc_msg"]):
                problems.append(f"expected {sp.expect} {sp.match!r}, got {fmt_rec(rec)}")
        elif not rec["ok"]:
            problems.append(f"assertion failed: {fmt_rec(rec)}")
        out.append({"support": sp, "problems": problems, "rec": rec, "python": python})
    return out


def format_support(r: dict) -> str:
    sp: Support = r["support"]
    if r.get("not_checked"):
        return f"[NOT CHECKED] {sp.id}: {r['not_checked']}"
    lines = [f"[{'PASS' if not r['problems'] else 'FAIL'}] {sp.id}  (supports replacement text)",
             f"    claim  : {sp.claim}", f"    env    : python {r['python']}" +
             "".join(" " + p for p in sp.env.pkgs)]
    out = (r["rec"].get("stdout") or "").strip()
    if out:
        for ln in out.splitlines()[:40]:
            lines.append(f"    output : {ln[:200]}")
    if r["rec"].get("ok") is False:
        lines.append(f"    raised : {fmt_rec(r['rec'])}")
    for p in r["problems"]:
        lines.append(f"    PROBLEM: {p}")
    return "\n".join(lines)


# ---------------------------------------------------------------------------------------
# log hygiene: no local absolute paths in saved output
# ---------------------------------------------------------------------------------------
_PATH_PATTERNS = [
    re.compile(r"(?:/private)?/var/folders/[^\s'\"<>)]+"),
    re.compile(r"[A-Za-z0-9_]*/T/ffk-verify-[A-Za-z0-9_]+[^\s'\"<>)]*"),
    re.compile(r"/Users/[^\s'\"<>)]+"),
    re.compile(r"/home/[^\s'\"<>)]+"),
    re.compile(r"(?:/private)?/tmp/[^\s'\"<>)]+"),
    re.compile(r"[A-Za-z]:\\Users\\[^\s'\"<>)]+"),
]


def sanitize(text: str) -> str:
    for pat in _PATH_PATTERNS:
        text = pat.sub("<path>", text)
    return text


def leaked_paths(text: str) -> list:
    return [m.group(0) for pat in _PATH_PATTERNS for m in pat.finditer(text)]


# ---------------------------------------------------------------------------------------
# smoke test with the REAL loader: merge the candidates into a COPY of the knowledge base and
# load it with fixfirst.domain (nothing under the repository is touched)
# ---------------------------------------------------------------------------------------
SMOKE = r'''
import json, sys
tmp, spec = sys.argv[1], json.load(sys.stdin)
sys.path.insert(0, tmp)
from fixfirst import domain, engine
from fixfirst.models import Fact
from fixfirst.reasoning import rule_base
kb = domain.load()
out = {"removed_index": len(kb["removed_index"]), "deprecated_index": len(kb["deprecated_index"]),
       "unmaintained_index": len(kb["unmaintained_index"]), "problems": [], "engine_ok": 0, "engine_total": 0}
for key in spec["removed"]:
    facts = domain.facts_for([key])
    preds = {f.predicate for f in facts}
    if not {"removed_from", "removed_in_version", "replacement"} <= preds:
        out["problems"].append(f"removed {key}: facts {sorted(preds)}")
for key in spec["deprecated"]:
    preds = {f.predicate for f in domain.facts_for([key])}
    if not {"deprecated_in", "deprecated_in_version", "replacement"} <= preds:
        out["problems"].append(f"deprecated {key}: facts {sorted(preds)}")
for key in spec["unmaintained"]:
    preds = {f.predicate for f in domain.facts_for([key])}
    if not {"unmaintained", "replacement"} <= preds:
        out["problems"].append(f"unmaintained {key}: facts {sorted(preds)}")
for key in spec["sources"]:
    if domain.source("kb:" + key) is None:
        out["problems"].append(f"source {key} does not resolve")

def fact(s, p, v):
    return Fact(fact_id=f"{s}:{p}:{v}", subject=s, predicate=p, value=v)

# Engine test: facts shaped like the ones evidence.py extracts from the real error message must
# make the matching D rule (D01 module, D02 api, D03 attribute, D04 kwarg, D07 usage) diagnose a
# version incompatibility, and rule P10 must render the entry's replacement text.
for item in spec["engine"]:
    out["engine_total"] += 1
    entity, kind = item["entity"], item["kind"]
    facts = [fact("issue-1", "exception", "Error"), fact(item["dist_node"], "installed_version", item["version"])]
    if kind == "module":
        facts.append(fact("issue-1", "missing_module", entity))
    elif kind == "api":
        # since the receiver ownership (D02/D03 need a removal_owner fact, which the product derives from the observed receiver)
        facts += [fact("issue-1", "api", entity), fact("issue-1", "removal_owner", entity)]
    elif kind == "attribute":
        facts += [fact("issue-1", "attribute", entity), fact("issue-1", "removal_owner", entity)]
    elif kind == "kwarg":
        facts += [fact("issue-1", "kwarg", entity), fact("issue-1", "callee", "callable:" + item["callee"])]
    elif kind == "usage":
        facts.append(fact("issue-1", "usage", entity))
    facts += domain.facts_for({entity})
    base = engine.run(rule_base(), facts)
    if ("issue-1", "diagnosis", "version_incompatibility") not in base.keys:
        out["problems"].append(f"engine: {entity} did not diagnose version_incompatibility")
        continue
    texts = [engine.render(p.template["explanation"], p.bindings) for p in engine.propose(rule_base(), base)]
    if not any(item["replacement"][:60] in t for t in texts):
        out["problems"].append(f"engine: advice for {entity} does not contain the replacement text")
        continue
    out["engine_ok"] += 1
print("@@SMOKE@@" + json.dumps(out))
'''


def merge_candidates_into_copy(kb_path: str, domain_path: str | None, cand_text: str, cand: dict) -> str:
    """Prepare the knowledge base of the loader smoke test (a copy). Returns how it was made:
      "baseline"  the explicit baseline (--domain) is the base and the candidates are appended to it;
      "shipped"   no baseline and the copy of the product's knowledge base already holds every candidate (they are integrated): nothing is added;
      "shipped+candidates"  no baseline and the copy holds none of them: they are appended.
    A copy that holds only some of the candidates is an error: appending them again defines the same sources twice."""
    if domain_path:
        shutil.copyfile(domain_path, kb_path)
        mode = "baseline"
    else:
        shipped = set(candidate_keys(tomllib.loads(open(kb_path, encoding="utf-8").read())))
        wanted = set(candidate_keys(cand))
        if wanted <= shipped:
            return "shipped"
        if wanted & shipped:
            raise RuntimeError("the knowledge base of the product holds only some of the candidates: pass --domain with the baseline "
                               "they are merged into (scripts/knowledge_verify/baseline/)")
        mode = "shipped+candidates"
    with open(kb_path, "a", encoding="utf-8") as f:
        f.write("\n\n" + cand_text)
    return mode


def loader_smoke(ws: Workspace, src_dir: str, domain_path: str | None, cand_text: str, cand: dict) -> dict:
    """src_dir is the directory that contains the `fixfirst` package (read only)."""
    tmp = os.path.join(ws.base, "ff-smoke")
    shutil.rmtree(tmp, ignore_errors=True)
    shutil.copytree(os.path.join(src_dir, "fixfirst"), os.path.join(tmp, "fixfirst"),
                    ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
    kb_path = os.path.join(tmp, "fixfirst", "knowledge", "domain.toml")
    try:
        mode = merge_candidates_into_copy(kb_path, domain_path, cand_text, cand)
    except RuntimeError as error:
        return {"problems": [str(error)]}
    spec = {"removed": [], "deprecated": [], "unmaintained": [], "sources": list(cand.get("sources", {})), "engine": []}
    for key, e in candidate_keys(cand).items():
        kind, _, rest = key.partition(":")
        if kind == "removed":
            spec["removed"].append(rest)
            ekind = e["kind"]
            callee = (e.get("callables") or [""])[0]
            dist = "dist:python" if e["distribution"].lower() == "python" else "dist:" + canon(e["distribution"])
            if ekind in ("module", "api", "attribute", "kwarg", "usage"):
                spec["engine"].append({"entity": rest, "kind": ekind, "dist_node": dist, "version": e["version"],
                                       "callee": callee, "replacement": e["replacement"]})
        elif kind == "deprecated":
            spec["deprecated"].append(rest)
        else:
            spec["unmaintained"].append("dist:" + rest.split(":", 1)[-1])
    py = ws.python_for(E("3.13", "packaging", "pydantic"))
    r = subprocess.run([py, "-I", "-B", "-c", SMOKE, tmp], input=json.dumps(spec), capture_output=True, text=True,
                       env=ws.env_vars, cwd=ws.neutral)
    for line in reversed(r.stdout.splitlines()):
        if line.startswith("@@SMOKE@@"):
            return {**json.loads(line[len("@@SMOKE@@"):]), "mode": mode}
    return {"problems": [f"loader crashed: {sanitize((r.stderr or r.stdout)[-500:])}"]}



