    Check(
        id='py3.13-usage-ssl-strict-missing-aki', dist='python', first_gone='3.13',
        covers=('usage:ssl strict certificate check: Missing Authority Key Identifier',), before=E('3.12', 'cryptography'),
        after=E('3.13', 'cryptography'),
        code='import datetime, os, socket, ssl, tempfile, threading\nfrom cryptography import x509\nfrom cryptography.hazmat.primitives import hashes, serialization\nfrom cryptography.hazmat.primitives.asymmetric import ec\nfrom cryptography.x509.oid import NameOID\n\nCA, LEAF, STRICT_OFF = \'good\', \'no-aki\', False\nd = tempfile.mkdtemp()\nnow = datetime.datetime.now(datetime.timezone.utc)\ndef name(cn): return x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, cn)])\ncakey, leafkey = ec.generate_private_key(ec.SECP256R1()), ec.generate_private_key(ec.SECP256R1())\nb = (x509.CertificateBuilder().subject_name(name("test ca")).issuer_name(name("test ca")).public_key(cakey.public_key())\n     .serial_number(x509.random_serial_number()).not_valid_before(now - datetime.timedelta(days=1)).not_valid_after(now + datetime.timedelta(days=30)))\nb = b.add_extension(x509.BasicConstraints(ca=True, path_length=None), critical=(CA != "bc-not-critical"))\nif CA != "no-keyusage":\n    b = b.add_extension(x509.KeyUsage(True, False, False, False, False, True, True, False, False), critical=True)\nb = b.add_extension(x509.SubjectKeyIdentifier.from_public_key(cakey.public_key()), critical=False)\ncacert = b.sign(cakey, hashes.SHA256())\nl = (x509.CertificateBuilder().subject_name(name("localhost")).issuer_name(cacert.subject).public_key(leafkey.public_key())\n     .serial_number(x509.random_serial_number()).not_valid_before(now - datetime.timedelta(days=1)).not_valid_after(now + datetime.timedelta(days=30))\n     .add_extension(x509.SubjectAlternativeName([x509.DNSName("localhost")]), critical=False)\n     .add_extension(x509.BasicConstraints(ca=False, path_length=None), critical=True))\nif LEAF != "no-aki":\n    l = l.add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(cakey.public_key()), critical=False)\nleaf = l.sign(cakey, hashes.SHA256())\ncafile, certfile, keyfile = (os.path.join(d, n) for n in ("ca.pem", "leaf.pem", "leaf.key"))\nopen(cafile, "wb").write(cacert.public_bytes(serialization.Encoding.PEM))\nopen(certfile, "wb").write(leaf.public_bytes(serialization.Encoding.PEM))\nopen(keyfile, "wb").write(leafkey.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))\nsrv = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)\nsrv.load_cert_chain(certfile, keyfile)\nls = socket.socket(); ls.bind(("127.0.0.1", 0)); ls.listen(1)\nport = ls.getsockname()[1]\ndef serve():\n    try:\n        c, _ = ls.accept()\n        with srv.wrap_socket(c, server_side=True) as t:\n            t.recv(10)\n    except Exception:\n        pass\nthreading.Thread(target=serve, daemon=True).start()\nctx = ssl.create_default_context(cafile=cafile)\nif STRICT_OFF:\n    ctx.verify_flags &= ~ssl.VERIFY_X509_STRICT\nwith socket.create_connection(("127.0.0.1", port), timeout=5) as s:\n    with ctx.wrap_socket(s, server_hostname="localhost") as t:\n        t.send(b"hello")\nprint("handshake ok")',
        expect='SSLCertVerificationError', match='Missing Authority Key Identifier', later=(E('3.14', 'cryptography'),),
        dists=('cryptography',), shape=False,
        note='a local TLS server presents a leaf signed by a generated CA; the client uses ssl.create_default_context(cafile=ca)',
        group='Python standard library (3.10 - 3.14)',
    ),
