        code='\nimport os, subprocess, sys, tempfile\nd = tempfile.mkdtemp()\nos.makedirs(os.path.join(d, "tests"))\nwith open(os.path.join(d, "tests", "__init__.py"), "w") as f:\n    f.write("")\nwith open(os.path.join(d, "tests", "test_a.py"), "w") as f:\n    f.write("import unittest\\nclass T(unittest.TestCase):\\n    def test_a(self):\\n        self.assertTrue(True)\\n")\nwith open(os.path.join(d, "setup.py"), "w") as f:\n    f.write("from setuptools import setup\\nsetup(name=\'demo\', version=\'0.1\', packages=[\'tests\'], test_suite=\'tests\')\\n")\nr = subprocess.run([sys.executable, "setup.py", "test"], cwd=d, capture_output=True, text=True)\nif r.returncode:\n    raise RuntimeError(" ".join((r.stdout + r.stderr).split())[-500:])\n',
