        code='\nimport os, subprocess, sys, tempfile, textwrap\n\ndef run_pytest(files, *args):\n    d = tempfile.mkdtemp()\n    for name, src in files.items():\n        p = os.path.join(d, name)\n        os.makedirs(os.path.dirname(p), exist_ok=True)\n        with open(p, "w") as f:\n            f.write(textwrap.dedent(src))\n    env = {k: v for k, v in os.environ.items() if not k.startswith("PYTEST")}\n    r = subprocess.run([sys.executable, "-m", "pytest", "-p", "no:cacheprovider", "-q", *args], cwd=d,\n                       capture_output=True, text=True, env=env)\n    return r.returncode, (r.stdout + r.stderr).replace(os.path.realpath(d), "<tmp>").replace(d, "<tmp>")\n\ndef report(rc, out, needle):\n    if rc == 0:\n        return\n    hits = [l.strip() for l in out.splitlines() if needle in l]\n    if not hits:\n        raise AssertionError("pytest failed without the expected text: " + out[-600:])\n    raise RuntimeError(hits[0])\nrc, out = run_pytest({\'test_a.py\': \'def check(x, y):\\n    assert x * x == y\\n\\ndef test_squared():\\n    yield check, 2, 4\\n\'})\nreport(rc, out, "\'yield\' keyword is allowed in fixtures, but not in tests")\n',
