    Support(
        id='sup-looseversion-vs-packaging', env=E('3.11', 'packaging', 'setuptools==65.5.0'),
        code="\nimport warnings\nwarnings.simplefilter('ignore')\nfrom distutils.version import LooseVersion, StrictVersion\nfrom packaging.version import Version, InvalidVersion\nassert LooseVersion('1.0rc1') > LooseVersion('1.0') and Version('1.0rc1') < Version('1.0')\nassert LooseVersion('1.0') != LooseVersion('1.0.0') and Version('1.0') == Version('1.0.0')\nassert LooseVersion('1.10') > LooseVersion('1.9') and Version('1.10') > Version('1.9')\nassert LooseVersion('1.2.3').version == [1, 2, 3] and Version('1.2.3').release == (1, 2, 3)\nfor bad in ('abc', '1.0-foo'):\n    LooseVersion(bad)\n    try:\n        Version(bad)\n    except InvalidVersion:\n        pass\n    else:\n        raise SystemExit('Version accepted ' + bad)\ntry:\n    StrictVersion('1.0rc1')\nexcept ValueError:\n    pass\nprint('pre-releases sort after the release for LooseVersion, before it for Version; 1.0 != 1.0.0 for LooseVersion; invalid strings raise InvalidVersion')\n",
        claim='LooseVersion/StrictVersion differ from packaging.version.Version: pre-release order, 1.0 vs 1.0.0, .version vs .release, strictness',
        covers=('api:distutils.version.LooseVersion', 'api:distutils.version.StrictVersion'),
        group='Python standard library (3.10 - 3.14)',
    ),
    Support(
        id='sup-strtobool', env=E('3.11'),
        code="\nimport warnings\nwarnings.simplefilter('ignore')\nfrom distutils.util import strtobool\ndef helper(v):\n    v = v.lower()\n    if v in ('y', 'yes', 't', 'true', 'on', '1'):\n        return 1\n    if v in ('n', 'no', 'f', 'false', 'off', '0'):\n        return 0\n    raise ValueError('invalid truth value %r' % (v,))\nfor v in ['y','Y','yes','YES','t','true','True','on','ON','1','n','N','no','f','false','False','off','0','maybe','','2',' yes']:\n    try: a = strtobool(v)\n    except ValueError: a = 'ValueError'\n    try: b = helper(v)\n    except ValueError: b = 'ValueError'\n    assert a == b, (v, a, b)\nprint('helper matches strtobool on', 22, 'inputs')\n",
        claim='the five-line helper reproduces distutils.util.strtobool (1/0 or ValueError)',
        covers=('api:distutils.util.strtobool',), group='Python standard library (3.10 - 3.14)',
    ),
