    Support(
        id='sup-ast-constant-classes', env=E('3.13'),
        code="\nimport ast, warnings\nwarnings.simplefilter('ignore')\ndef num(n): return isinstance(n, ast.Constant) and isinstance(n.value, (int, float, complex)) and not isinstance(n.value, bool)\ndef name_constant(n): return isinstance(n, ast.Constant) and (n.value is None or isinstance(n.value, bool))\ndef ellipsis(n): return isinstance(n, ast.Constant) and n.value is ...\nfor v in (1, 1.5, 2j, True, False, None, 'x', b'x', ...):\n    c = ast.Constant(v)\n    assert isinstance(c, ast.Num) == num(c), v\n    assert isinstance(c, ast.Str) == (isinstance(c, ast.Constant) and isinstance(c.value, str)), v\n    assert isinstance(c, ast.Bytes) == (isinstance(c, ast.Constant) and isinstance(c.value, bytes)), v\n    assert isinstance(c, ast.NameConstant) == name_constant(c), v\n    assert isinstance(c, ast.Ellipsis) == ellipsis(c), v\nassert ast.Constant(5).n == 5 == ast.Constant(5).value and ast.Constant('s').s == 's'\nprint('isinstance(node, ast.Num) is Constant with an int/float/complex value that is not a bool; NameConstant is None/bool')\n",
        claim='ast.Num/Str/Bytes/NameConstant/Ellipsis isinstance tests equal Constant plus a type test on .value (bool is excluded from Num); .n/.s are .value',
        covers=('api:ast.Num', 'api:ast.Str', 'api:ast.Bytes', 'api:ast.NameConstant', 'api:ast.Ellipsis', 'api:Constant.n', 'api:Constant.s'),
        group='Python standard library (3.10 - 3.14)',
    ),
