    Support(
        id='sup-pkg_resources-vs-importlib', env=E('3.12', 'setuptools==81.0.0', 'packaging', 'pip'),
        code="\nimport warnings\nwarnings.simplefilter('ignore')\nimport importlib.metadata as im, importlib.resources as ir, pkg_resources\nfrom packaging.requirements import Requirement\nfrom packaging.version import Version\nassert pkg_resources.get_distribution('pip').version == im.version('pip')\nassert sorted(e.name for e in pkg_resources.iter_entry_points('console_scripts')) == sorted(e.name for e in im.entry_points(group='console_scripts'))\nassert [e.name for e in pkg_resources.iter_entry_points('console_scripts', 'pip')] == [e.name for e in im.entry_points(group='console_scripts', name='pip')]\ntry:\n    pkg_resources.get_distribution('no-such-dist-xyz')\nexcept pkg_resources.DistributionNotFound:\n    pass\ntry:\n    im.version('no-such-dist-xyz')\nexcept im.PackageNotFoundError:\n    pass\nassert pkg_resources.resource_string('email', '__init__.py') == ir.files('email').joinpath('__init__.py').read_bytes()\nassert pkg_resources.resource_exists('email', 'mime') and ir.files('email').joinpath('mime').is_dir()\nassert pkg_resources.resource_isdir('email', 'mime') and not pkg_resources.resource_isdir('email', '__init__.py')\nassert sorted(pkg_resources.resource_listdir('email', 'mime')) == sorted(p.name for p in ir.files('email').joinpath('mime').iterdir())\nwith ir.as_file(ir.files('email').joinpath('__init__.py')) as p:\n    assert str(p) == pkg_resources.resource_filename('email', '__init__.py')\nwith ir.files('email').joinpath('__init__.py').open('rb') as f1, pkg_resources.resource_stream('email', '__init__.py') as f2:\n    assert f1.read() == f2.read()\npv = pkg_resources.parse_version('1.0rc1')\nassert isinstance(pv, Version) and pv < Version('1.0')\nreq = pkg_resources.Requirement.parse('Foo[bar]>=1.0,<2')\nreq2 = Requirement('Foo[bar]>=1.0,<2')\nassert req.project_name == req2.name and req.extras == tuple(req2.extras) and str(req.specifier) == str(req2.specifier)\nnames = {d.project_name.lower() for d in pkg_resources.working_set}\nassert 'pip' in names and 'pip' in {d.metadata['Name'].lower() for d in im.distributions()}\nprint('get_distribution/iter_entry_points/DistributionNotFound/resource_*/parse_version/Requirement/working_set map to importlib.metadata, importlib.resources and packaging')\n",
        claim='the replacements named for pkg_resources.get_distribution, iter_entry_points, DistributionNotFound, resource_*, parse_version, Requirement and working_set behave the same',
        covers=('api:pkg_resources.get_distribution', 'api:pkg_resources.iter_entry_points', 'api:pkg_resources.resource_filename'),
        group='setuptools / pkg_resources / distutils shim',
    ),
