    Support(
        id='sup-uv-venv-never-has-setuptools', env=E('3.11'),
        code='\nimport os, shutil, subprocess, sys, tempfile\nuv = shutil.which("uv")\nassert uv, "uv not on PATH"\nd = os.path.join(tempfile.mkdtemp(), "v")\nsubprocess.run([uv, "venv", "--quiet", "--python", sys.executable, d], check=True, capture_output=True)\npy = os.path.join(d, "bin", "python")\nr = subprocess.run([py, "-I", "-c", "import pkg_resources"], capture_output=True, text=True)\nassert r.returncode != 0 and "No module named \'pkg_resources\'" in r.stderr, r.stderr\nprint("uv venv on Python 3.11 contains no setuptools either:", r.stderr.strip().splitlines()[-1])\n',
        claim='environments made with `uv venv` never contain setuptools, even on Python 3.11, where `python -m venv` still bundles it (FixFirst rule H03 words the cause as a 3.12 change)',
        group='setuptools / pkg_resources / distutils shim',
    ),
    Support(
        id='sup-st82-resources-traversable', env=E('3.12'),
        code='\nimport importlib.resources as resources, importlib.resources.abc as abc, pathlib, sys, tempfile\nwith tempfile.TemporaryDirectory() as tmp:\n    roots = [pathlib.Path(tmp, "one"), pathlib.Path(tmp, "two")]\n    for root in roots:\n        directory = root / "kbprobe_namespace" / "data"\n        directory.mkdir(parents=True)\n        (directory / (root.name + ".txt")).write_text("probe")\n    regular = pathlib.Path(tmp, "reg", "kbprobe_regular")\n    regular.mkdir(parents=True)\n    (regular / "__init__.py").write_text("")\n    (regular / "blob.bin").write_bytes(b"\\xff\\x00abc")\n    (regular / "text.txt").write_text("hello")\n    sys.path[:0] = [str(r) for r in roots] + [str(regular.parent)]\n    public = [n for n in vars(abc.Traversable) if not n.startswith("_")]\n    assert "is_file" in public and "is_dir" in public and "exists" not in public, public\n    value = resources.files("kbprobe_namespace") / "data"\n    assert type(value).__name__ == "MultiplexedPath", type(value)\n    assert value.is_dir() and (value.is_file() or value.is_dir())\n    assert not hasattr(value, "exists")\n    assert not ((resources.files("kbprobe_namespace") / "missing").is_file() or (resources.files("kbprobe_namespace") / "missing").is_dir())\n    reg = resources.files("kbprobe_regular")\n    assert (reg / "blob.bin").read_bytes() == b"\\xff\\x00abc"\n    try:\n        (reg / "blob.bin").read_text(encoding="utf-8")\n        raise SystemExit("read_text unexpectedly decoded binary data")\n    except UnicodeDecodeError:\n        pass\n    assert (reg / "text.txt").open("rb").read() == b"hello"\n    assert {"blob.bin", "text.txt"} <= {p.name for p in reg.iterdir()}\n    assert (reg / "text.txt").is_file() and not (reg / "text.txt").is_dir()\n',
        claim='files(package) / name is a Traversable: is_file()/is_dir() exist, exists() does not (a namespace package returns a MultiplexedPath without it); read_bytes() keeps bytes where read_text() fails on binary data; (is_file() or is_dir()) is the portable existence check',
        covers=('api:pkg_resources.resource_filename', 'api:pkg_resources.resource_string', 'api:pkg_resources.resource_stream', 'api:pkg_resources.resource_listdir', 'api:pkg_resources.resource_exists', 'api:pkg_resources.resource_isdir'),
        group='setuptools / pkg_resources / distutils shim',
    ),
