    Support(
        id='sup-sp-1.13-windows-ode-tri-bspline', env=E('3.12', 'scipy==1.12.0', 'numpy==1.26.4'),
        code="import warnings\nwarnings.simplefilter('ignore')\nimport numpy as np\nimport scipy.linalg as L\nimport scipy.signal as S\nfrom scipy.interpolate import BSpline\nargs = {'gaussian': (2.0,), 'general_gaussian': (1.5, 2.0), 'kaiser': (8.0,), 'chebwin': (60,), 'exponential': (None, 1.0), 'tukey': (0.5,)}\nfor n in ['barthann', 'bartlett', 'blackman', 'blackmanharris', 'bohman', 'boxcar', 'chebwin', 'cosine', 'exponential', 'flattop',\n          'gaussian', 'general_gaussian', 'hamming', 'hann', 'kaiser', 'nuttall', 'parzen', 'triang', 'tukey']:\n    a = args.get(n, ())\n    assert np.array_equal(getattr(S, n)(11, *a), getattr(S.windows, n)(11, *a)), n\nsys = ([1.0], [1.0, 1.0]); T = np.linspace(0, 5, 51); U = np.sin(T)\nassert np.allclose(S.lsim2(sys, U, T)[1], S.lsim(sys, U, T)[1], atol=1e-3)\nassert np.allclose(S.impulse2(sys, T=T)[1], S.impulse(sys, T=T)[1], atol=1e-3)\nassert np.allclose(S.step2(sys, T=T)[1], S.step(sys, T=T)[1], atol=1e-3)\nx = np.linspace(-3, 3, 41)\ncub = BSpline.basis_element([-2, -1, 0, 1, 2], extrapolate=False)(x); cub = np.where(np.isnan(cub), 0.0, cub)\nassert np.allclose(S.cubic(x), cub)\nquad = BSpline.basis_element([-1.5, -0.5, 0.5, 1.5], extrapolate=False)(x); quad = np.where(np.isnan(quad), 0.0, quad)\nassert np.allclose(S.quadratic(x), quad)\nfor n in (1, 2, 3):\n    knots = np.arange(-(n + 1) / 2, (n + 3) / 2)\n    bs = BSpline.basis_element(knots, extrapolate=False)(x); bs = np.where(np.isnan(bs), 0.0, bs)\n    assert np.allclose(S.bspline(x, n), bs), n\nm = np.arange(1.0, 13.0).reshape(3, 4)\nfor k in (-1, 0, 1):\n    assert np.array_equal(L.triu(m, k), np.triu(m, k)) and np.array_equal(L.tril(m, k), np.tril(m, k))\nassert np.array_equal(L.tri(3, 4, 1), np.tri(3, 4, 1))\n",
        claim='signal.<window> equals signal.windows.<window>; lsim2/impulse2/step2 approximate lsim/impulse/step; tri* equal numpy; bspline family equals BSpline.basis_element',
        covers=('api:scipy.signal.hann', 'api:scipy.signal.hamming', 'api:scipy.signal.lsim2', 'api:scipy.signal.impulse2', 'api:scipy.signal.step2', 'api:scipy.signal.bspline', 'api:scipy.signal.quadratic', 'api:scipy.signal.cubic', 'api:scipy.linalg.tri', 'api:scipy.linalg.triu', 'api:scipy.linalg.tril'),
        group='NumPy and SciPy',
    ),
