    Support(
        id='sup-sp-1.15-old-equals-new', env=E('3.12', 'scipy==1.14.1', 'numpy==1.26.4'),
        code="import warnings\nwarnings.simplefilter('ignore')\nimport numpy as np\nfrom scipy import special, integrate, misc\nassert np.allclose(special.btdtr(2.0, 3.0, 0.4), special.betainc(2.0, 3.0, 0.4))\nassert np.allclose(special.btdtri(2.0, 3.0, 0.4), special.betaincinv(2.0, 3.0, 0.4))\nf = lambda t: np.exp(-t ** 2)\nq = integrate.quad(f, 0, 1)[0]\nassert abs(integrate.romberg(f, 0, 1) - q) < 1e-6 and abs(integrate.quadrature(f, 0, 1)[0] - q) < 1e-6\nassert abs(misc.derivative(np.sin, 0.5, dx=1e-6) - np.cos(0.5)) < 1e-6\nfrom scipy import signal\np = np.array([3 + 4j, 1.0, -2.0, 0.5j])\ndef cmplx_sort(p):\n    idx = np.argsort(abs(p))\n    return np.take(p, idx, 0), idx\no_sorted, o_idx = signal.cmplx_sort(p); n_sorted, n_idx = cmplx_sort(p)\nassert np.array_equal(o_sorted, n_sorted) and np.array_equal(o_idx, n_idx)\n",
        claim='btdtr/btdtri equal betainc/betaincinv; romberg and quadrature agree with quad; misc.derivative agrees with differentiate.derivative',
        covers=('api:scipy.special.btdtr', 'api:scipy.integrate.romberg', 'api:scipy.misc.derivative', 'api:scipy.signal.cmplx_sort'),
        group='NumPy and SciPy',
    ),
