        code="import warnings\nwarnings.simplefilter('ignore')\nimport matplotlib as mpl\nmpl.use('Agg')\nimport matplotlib.pyplot as plt\nimport numpy as np\npairs = {'seaborn': 'seaborn-v0_8', 'seaborn-whitegrid': 'seaborn-v0_8-whitegrid', 'seaborn-darkgrid': 'seaborn-v0_8-darkgrid', 'seaborn-white': 'seaborn-v0_8-white', 'seaborn-ticks': 'seaborn-v0_8-ticks', 'seaborn-dark': 'seaborn-v0_8-dark', 'seaborn-paper': 'seaborn-v0_8-paper', 'seaborn-poster': 'seaborn-v0_8-poster'}\nfor old, new in pairs.items():\n    with plt.style.context(old):\n        a = dict(mpl.rcParams)\n    with plt.style.context(new):\n        b = dict(mpl.rcParams)\n    assert a == b, old\n",
