        code="import warnings\nwarnings.simplefilter('ignore')\nfrom werkzeug.security import safe_str_cmp\nimport hmac\nassert safe_str_cmp('abc', 'abc') is hmac.compare_digest('abc', 'abc') is True\nassert safe_str_cmp('abc', 'abd') is hmac.compare_digest('abc', 'abd') is False\nassert safe_str_cmp(b'abc', b'abc') is hmac.compare_digest(b'abc', b'abc') is True\nassert safe_str_cmp('\\u00e9', '\\u00e9') is True and safe_str_cmp('abc', b'abc') is True\nfor a, b in [('\\u00e9', '\\u00e9'), ('abc', b'abc')]:\n    try:\n        hmac.compare_digest(a, b)\n        raise SystemExit('no TypeError')\n    except TypeError:\n        pass\nassert hmac.compare_digest('\\u00e9'.encode(), '\\u00e9'.encode()) is True\n",
