    Support(
        id='sup-django-render-requestcontext', env=E('3.9', 'Django==2.2.28'),
        code="import warnings\nwarnings.simplefilter('ignore')\nimport sys, types\nfrom django.conf import settings\nimport django\ncp = types.ModuleType('ff_cp')\ncp.cp = lambda request: {'extra': 'CP'}\nsys.modules['ff_cp'] = cp\nsettings.configure(SECRET_KEY='x', INSTALLED_APPS=[], TEMPLATES=[{'BACKEND': 'django.template.backends.django.DjangoTemplates', 'OPTIONS': {'loaders': [('django.template.loaders.locmem.Loader', {'t.html': '[{{ extra }}]'})], 'context_processors': ['ff_cp.cp']}}])\ndjango.setup()\nfrom django.shortcuts import render, render_to_response\nfrom django.test import RequestFactory\nassert render_to_response('t.html', {}).content == b'[]'\nassert render(RequestFactory().get('/'), 't.html', {}).content == b'[CP]'\n",
        claim='render() runs context processors while render_to_response() does not',
        covers=('api:django.shortcuts.render_to_response',), group='Django, Flask, Werkzeug, Jinja2, MarkupSafe, itsdangerous',
    ),
