        code='\ntry:\n    import httpx2 as httpx          # openai 3.x ships HTTPX2\nexcept ImportError:\n    import httpx\nimport io\nimport openai\nfrom openai import OpenAI\n\n\ndef handler(request):\n    path = request.url.path\n    if path.endswith("/chat/completions"):\n        body = {"id": "c1", "object": "chat.completion", "created": 1, "model": "m",\n                "choices": [{"index": 0, "finish_reason": "stop", "message": {"role": "assistant", "content": "Hi there"}}]}\n    elif path.endswith("/completions"):\n        body = {"id": "c1", "object": "text_completion", "created": 1, "model": "m",\n                "choices": [{"index": 0, "finish_reason": "stop", "text": "Hi text", "logprobs": None}]}\n    elif path.endswith("/embeddings"):\n        body = {"object": "list", "model": "m", "data": [{"object": "embedding", "index": 0, "embedding": [0.1, 0.2]}],\n                "usage": {"prompt_tokens": 1, "total_tokens": 1}}\n    elif path.endswith("/moderations"):\n        body = {"id": "m1", "model": "m", "results": [{"flagged": False, "categories": {}, "category_scores": {}}]}\n    elif path.endswith("/images/generations"):\n        body = {"created": 1, "data": [{"url": "https://example.invalid/i.png"}]}\n    elif path.endswith("/audio/transcriptions"):\n        body = {"text": "hello transcript"}\n    else:\n        body = {"object": "list", "data": []}\n    return httpx.Response(200, json=body, request=request)\n\n\nclient = OpenAI(api_key="test-key", http_client=httpx.Client(transport=httpx.MockTransport(handler)))\nchat = client.chat.completions.create(model="m", messages=[{"role": "user", "content": "Hello"}])\nassert chat.choices[0].message.content == "Hi there" and chat.model_dump()["choices"][0]["message"]["content"] == "Hi there"\nassert client.completions.create(model="m", prompt="Hello").choices[0].text == "Hi text"\nassert client.embeddings.create(model="m", input="Hello").data[0].embedding == [0.1, 0.2]\nassert client.moderations.create(input="Hello").results[0].flagged is False\nassert client.images.generate(prompt="a cat", n=1, size="256x256").data[0].url.endswith("i.png")\naudio = io.BytesIO(b"RIFF")\naudio.name = "speech.wav"\nassert client.audio.transcriptions.create(model="whisper-1", file=audio).text == "hello transcript"\nassert list(client.models.list()) == [] and list(client.files.list()) == [] and list(client.fine_tuning.jobs.list()) == []\nassert hasattr(client.files, "content") or hasattr(client.files, "retrieve_content")   # content() from 1.2.1, retrieve_content() before\nfor resource, names in (("files", ("create", "list", "retrieve", "delete")),\n                        ("fine_tuning.jobs", ("create", "list", "retrieve", "cancel", "list_events")),\n                        ("models", ("list", "retrieve", "delete")), ("images", ("generate", "create_variation", "edit"))):\n    target = client\n    for part in resource.split("."):\n        target = getattr(target, part)\n    assert all(hasattr(target, n) for n in names), resource\nassert hasattr(client.audio, "translations") and hasattr(openai, "AsyncOpenAI")\nassert not hasattr(client, "engines")   # openai.Engine has no resource of its own in 1.x; models.list()/retrieve() are the nearest calls\nfor name in ("OpenAIError", "APIError", "APIConnectionError", "APITimeoutError", "APIStatusError", "BadRequestError",\n             "AuthenticationError", "PermissionDeniedError", "NotFoundError", "RateLimitError", "InternalServerError"):\n    assert hasattr(openai, name), name\n',
