        code="\nimport ssl\nimport urllib3\nfrom urllib3.util.retry import Retry\nfrom urllib3.util.ssl_ import create_urllib3_context\nfrom urllib3.connection import HTTPSConnection\n\n# allowed_methods replaces method_whitelist; None retries every verb\nassert Retry(allowed_methods=['GET', 'HEAD'])._is_method_retryable('GET')\nassert not Retry(allowed_methods=['GET', 'HEAD'])._is_method_retryable('POST')\nassert Retry(allowed_methods=None)._is_method_retryable('POST')\n# an explicit SSL context with a cipher string replaces edits of DEFAULT_CIPHERS\ncontext = create_urllib3_context(ciphers='DEFAULT:@SECLEVEL=1')\nassert isinstance(context, ssl.SSLContext)\npool = urllib3.PoolManager(ssl_context=context)\nassert pool.connection_pool_kw['ssl_context'] is context\n# HTTPSConnection is the current name of the connection class, HAS_SNI lives in ssl\nassert HTTPSConnection.__name__ == 'HTTPSConnection' and ssl.HAS_SNI is True\n# a response can be built directly\nresponse = urllib3.response.HTTPResponse(body=b'x', headers={'Content-Type': 'text/plain'}, status=200)\nassert response.status == 200 and response.data == b'x'\n",
