# =======================================================================================
# Audit of the EXISTING entries (generated from domain.toml itself; not candidates)
# =======================================================================================
PYS = ["3.9", "3.10", "3.11", "3.12", "3.13", "3.14"]
# modules that exist on other platforms only: they are not built on the machine that ran the audit
PLATFORM_ONLY = {"msilib": "Windows only", "nis": "not built in these interpreters", "ossaudiodev": "not built in these interpreters",
                 "spwd": "not built in these interpreters"}


def _prev(v):
    return PYS[PYS.index(v) - 1]


def _later(v):
    return tuple(E(x) for x in PYS[PYS.index(v) + 1:])


def audit_checks(domain: dict) -> list:
    out = []

    def mk(cid, key, ver, code, expect, match):
        out.append(Check("audit-" + cid, "python", ver, (key,), E(_prev(ver)), E(ver), code, expect, match,
                         later=_later(ver), group="audit: existing standard-library [[removed]] entries"))

    for e in domain.get("removed", []):
        if e["distribution"].lower() != "python" or e["version"] not in PYS[1:]:
            continue
        ver = e["version"]
        if e["kind"] == "module":
            for n in e["names"]:
                mk(f"module-{n}", f"module:{n}", ver, f"import {n}", "ModuleNotFoundError", f"No module named '{n}'")
        elif e["kind"] == "api":
            for n in e["names"]:
                mod = e["module"]
                mk(f"api-{mod}.{n}-attr", f"api:{mod}.{n}", ver, f"import {mod}\n{mod}.{n}", "AttributeError", f"has no attribute '{n}'")
                mk(f"api-{mod}.{n}-import", f"api:{mod}.{n}", ver, f"from {mod} import {n}", "ImportError", f"cannot import name '{n}'")
        elif e["kind"] == "attribute" and "unittest.TestCase" in e.get("owners", []):
            for n in e["names"]:
                mk(f"attribute-{n}", f"attribute:{n}", ver,
                   f"import unittest\nclass T(unittest.TestCase):\n    def runTest(self):\n        pass\nT().{n}",
                   "AttributeError", f"'T' object has no attribute '{n}'")
    return out


def audit_deprecated_checks(domain: dict) -> list:
    out = []
    snippets = {
        ("ast", "Num"): "import ast\nast.Num", ("ast", "Str"): "import ast\nast.Str",
        ("ast", "Bytes"): "import ast\nast.Bytes", ("ast", "NameConstant"): "import ast\nast.NameConstant",
        ("ast", "Ellipsis"): "import ast\nast.Ellipsis",
        ("pkgutil", "find_loader"): "import pkgutil\npkgutil.find_loader('json')",
        ("pkgutil", "get_loader"): "import pkgutil\npkgutil.get_loader('json')",
        ("datetime.datetime", "utcnow"): "import datetime\ndatetime.datetime.utcnow()",
        ("datetime.datetime", "utcfromtimestamp"): "import datetime\ndatetime.datetime.utcfromtimestamp(0)",
        ("locale", "getdefaultlocale"): "import locale\nlocale.getdefaultlocale()",
    }
    for e in domain.get("deprecated", []):
        if e["distribution"].lower() != "python":
            continue
        ver = e["version"]
        for n in e["names"]:
            code = snippets.get((e["module"], n))
            if not code or ver not in PYS[1:]:
                continue
            last = PYS.index(e["removal"]) if e.get("removal") in PYS else len(PYS)
            later_envs = tuple(E(x) for x in PYS[PYS.index(ver) + 1:last])
            out.append(Check(f"audit-deprecated-{e['module']}.{n}", "python", ver, (f"api:{e['module']}.{n}",),
                             E(_prev(ver)), E(ver), code, kind="deprecated", warn=rf"{n}\b.*deprecated|deprecated.*{n}\b",
                             later=later_envs, group="audit: existing [[deprecated]] entries"))
    return out


# =======================================================================================
# Report
# =======================================================================================
def _heading(title: str) -> str:
    return "\n" + "=" * 100 + f"\n{title}\n" + "=" * 100


# =======================================================================================
# Machine-readable receipts (full, redacted): one record per check / probe, with the snippet, the environments and the observed text
# =======================================================================================
def _clean(obj, limit=4000):
    if isinstance(obj, str):
        return sanitize(obj)[:limit]
    if isinstance(obj, dict):
        return {str(k): _clean(v, limit) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_clean(v, limit) for v in obj]
    return obj if isinstance(obj, (int, float, bool)) or obj is None else sanitize(str(obj))[:limit]


def _rec(rec):
    out = {k: _clean(rec[k]) for k in ("ok", "exc_type", "exc_msg", "stdout", "error") if rec.get(k) not in (None, "")}
    if "ok" in rec:
        out["ok"] = rec["ok"]
    out["warnings"] = [[_clean(w.get("category")), _clean(w.get("message"), 400)] for w in (rec.get("warnings") or [])[:5]]
    return out


def _digest(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def check_receipt(r):
    c = r["check"]
    envs = {"before": c.before, "after": c.after, **{f"later{i}": e for i, e in enumerate(c.later)}}
    info = r.get("envs") or {}
    roles = {}
    for role, rec in r.get("recs", {}).items():
        env = envs.get(role)
        roles[role] = {"env": env.label() if env else "", "python": (info.get(role) or {}).get("python"),
                       "dists": _clean((info.get(role) or {}).get("dists")), **_rec(rec)}
    return {"id": c.id, "group": c.group, "dist": c.dist, "first_gone": c.first_gone, "kind": c.kind, "covers": list(c.covers),
            "expect": c.expect, "match": c.match, "status": "pass" if not r["problems"] else "fail",
            "problems": _clean(r["problems"]), "code_sha256": _digest(c.code), "code": c.code, "roles": roles,
            "info": _clean(r.get("info"))}


def support_receipt(r):
    sp = r["support"]
    status = "not_checked" if r.get("not_checked") else ("pass" if not r["problems"] else "fail")
    return {"id": sp.id, "claim": sp.claim, "covers": list(sp.covers), "env": sp.env.label(), "python": r.get("python"),
            "expect": sp.expect, "match": sp.match, "status": status, "problems": _clean(r["problems"]),
            "code_sha256": _digest(sp.code), "code": sp.code, **_rec(r.get("rec") or {})}


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    here = os.path.dirname(os.path.abspath(__file__))
    ap.add_argument("--candidates", nargs="+", default=None,
                    help="candidate file(s) to verify (default: candidates.toml and, if present, candidates-optional.toml next to this script)")
    ap.add_argument("--domain", default=os.environ.get("FIXFIRST_DOMAIN_TOML"),
                    help="path of the FixFirst domain.toml (read only); needed for collision checks and the audit")
    ap.add_argument("--fixfirst-src", help="directory that contains the `fixfirst` package: merge the candidates into a COPY "
                                           "of its knowledge base and run the real loader and rule engine on every entry")
    ap.add_argument("--only", default="", help="run only checks whose id contains this text (skips the cross-checks)")
    ap.add_argument("--skip-audit", action="store_true", help="do not audit the existing entries")
    ap.add_argument("--keep-envs", action="store_true", help="keep the throwaway environments")
    ap.add_argument("--receipts", help="write a full, redacted machine-readable record of every check and probe to this JSON file")
    a = ap.parse_args(argv)
    t0 = time.time()
    cand_paths = a.candidates or [p for p in (os.path.join(here, "candidates.toml"), os.path.join(here, "candidates-optional.toml"))
                                  if os.path.exists(p)]
    cand_text = "\n".join(open(p, encoding="utf-8").read() for p in cand_paths)   # a source defined twice is a TOML error: good
    cand = tomllib.loads(cand_text)
    domain = tomllib.loads(open(a.domain, encoding="utf-8").read()) if a.domain else {}
    pythons = find_pythons()
    uv_version = subprocess.run([UV, "--version"], capture_output=True, text=True).stdout.strip()
    lines = []

    def out(s=""):
        s = sanitize(s)
        lines.append(s)
        print(s, flush=True)

    out("FixFirst knowledge candidates: verification log")
    out(f"generated   : {datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%S')} UTC by verify.py")
    out(f"tooling     : {uv_version}; verify.py runs on Python {sys.version.split()[0]}")
    ws = Workspace(keep=a.keep_envs)
    try:
        ver_lines = []
        for mm in sorted(pythons, key=lambda v: tuple(int(x) for x in v.split("."))):
            r = subprocess.run([pythons[mm], "-I", "-c", "import sys; print(sys.version.split()[0])"], capture_output=True, text=True)
            ver_lines.append(r.stdout.strip())
        out(f"interpreters: {', '.join(ver_lines)} (CPython, uv-managed; each snippet runs with `python -I -B` from an empty directory)")
        out(f"files       : {', '.join(os.path.basename(p) for p in cand_paths)}")
        out(f"candidates  : {len(cand.get('removed', []))} [[removed]] blocks, {len(cand.get('deprecated', []))} [[deprecated]] blocks, "
            f"{len(cand.get('unmaintained', []))} [[unmaintained]] blocks, {len(cand.get('sources', {}))} new sources")
        checks = [c for c in CHECKS if a.only in c.id]
        supports = [s for s in SUPPORTS if a.only in s.id]
        out(f"checks      : {len(checks)} candidate checks, {len(supports)} supporting probes")
        failures = 0
        aresults, asup, smoke, problems = [], [], {}, []

        # ---- 1. candidate checks
        results = run_checks(ws, checks)
        group = None
        for r in results:
            if r["check"].group != group:
                group = r["check"].group
                out(_heading("CHECKS: " + group))
            out(format_result(r))
            failures += bool(r["problems"])
        passed = sum(1 for r in results if not r["problems"])

        # ---- 2. supporting probes
        sresults = run_supports(ws, supports)
        if sresults:
            out(_heading("SUPPORTING PROBES (evidence for replacement texts, rejected items and unmaintained entries)"))
        for r in sresults:
            out(format_support(r))
        sfail = sum(1 for r in sresults if r["problems"])
        failures += sfail

        # ---- 3. cross-checks of candidates.toml
        if not a.only:
            out(_heading("CROSS-CHECK OF THE CANDIDATE FILES"))
            if domain:
                problems += validate_candidates(cand, domain)
            else:
                problems.append("no --domain given: collision and source checks skipped")
            problems += coverage_problems(cand, results, sresults)
            used = {index_key(e, n) for e in candidate_entries(cand) if e["_table"] != "unmaintained" for n in e["names"]}
            orphans = sorted({k for r in results for k in r["check"].covers if k not in used})
            keys = candidate_keys(cand)
            by_table = {"removed": 0, "deprecated": 0, "unmaintained": 0}
            for k in keys:
                by_table[k.split(":", 1)[0]] += 1
            out(f"candidate keys   : {by_table['removed']} removed, {by_table['deprecated']} deprecated, {by_table['unmaintained']} unmaintained")
            out(f"verified keys    : every key needs a passing check with the same distribution and first-gone version")
            for p in problems:
                out(f"PROBLEM: {p}")
            if orphans:
                out(f"NOTE: {len(orphans)} checked keys are not used by any entry: {', '.join(orphans[:20])}")
            out(f"cross-check problems: {len(problems)}")
            failures += len(problems)

        # ---- 4. audit of existing entries
        if domain and not a.skip_audit and not a.only:
            audit = audit_checks(domain) + audit_deprecated_checks(domain) + [c for c in AUDIT]
            aresults = run_checks(ws, audit)
            out(_heading("AUDIT OF EXISTING knowledge-base entries (not candidates)"))
            conf = bad = find = plat = 0
            for r in aresults:
                c = r["check"]
                key = c.covers[0].split(":", 1)[-1] if c.covers else ""
                if r["problems"] and key.split(":")[-1] in PLATFORM_ONLY and c.id.startswith("audit-module-"):
                    plat += 1
                    out(f"[UNVERIFIABLE HERE] {c.id}: the module was never importable on this platform ({PLATFORM_ONLY[key.split(':')[-1]]}); "
                        f"its removal in {c.first_gone} rests on PEP 594 / What's New only")
                    continue
                if r["problems"] and c.finding:
                    find += 1
                    out(format_result(r))
                elif r["problems"]:
                    bad += 1
                    out(format_result(r))
                else:
                    conf += 1
            out(f"audit: {conf} existing checks confirmed, {find} FINDINGS (claim contradicted), {bad} unexpected failures, {plat} unverifiable on this platform")
            for r in aresults:
                if not r["problems"] and r["check"].id.startswith("audit-") and not r["check"].id.startswith(("audit-api-", "audit-module-", "audit-attribute-", "audit-deprecated")):
                    pass
            asup = run_supports(ws, AUDIT_SUPPORTS)
            for r in asup:
                out(format_support(r))
            bad += sum(1 for r in asup if r["problems"])
            failures += bad

        # ---- 5. real loader and rule engine
        if a.fixfirst_src and not a.only:
            out(_heading("SMOKE TEST WITH THE REAL FIXFIRST LOADER AND RULE ENGINE (a copy of the knowledge base; the repository is untouched)"))
            smoke = loader_smoke(ws, a.fixfirst_src, a.domain, cand_text, cand)
            for k in ("mode", "removed_index", "deprecated_index", "unmaintained_index", "engine_ok", "engine_total"):
                if k in smoke:
                    out(f"{k:20s}: {smoke[k]}")
            for p in smoke.get("problems", []):
                out(f"PROBLEM: {p}")
            out(f"smoke problems: {len(smoke.get('problems', []))}")
            failures += len(smoke.get("problems", []))
        out(_heading("SUMMARY"))
        out(f"candidate checks passed : {passed} of {len(results)}")
        out(f"supporting probes passed: {len(sresults) - sfail} of {len(sresults)}")
        not_checked = sum(1 for r in sresults + asup if r.get("not_checked"))
        out(f"probes NOT CHECKED      : {not_checked}" + ("   <- the run is INCOMPLETE; this is not a pass" if not_checked else ""))
        out(f"total failures          : {failures}")
        out(f"elapsed                 : {time.time() - t0:.0f} s")
        if a.receipts:
            receipt = {
                "schema": 1,
                "generated_utc": datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                "tool": {"verify_py_sha256": hashlib.sha256(open(os.path.abspath(__file__), "rb").read()).hexdigest(),
                         "uv": uv_version, "verify_python": sys.version.split()[0], "interpreters": ver_lines},
                "files": {os.path.basename(p): hashlib.sha256(open(p, "rb").read()).hexdigest() for p in cand_paths},
                "domain_toml_sha256": hashlib.sha256(open(a.domain, "rb").read()).hexdigest() if a.domain else None,
                "summary": {"candidate_checks": len(results), "candidate_checks_passed": passed, "supporting_probes": len(sresults),
                            "supporting_probes_passed": len(sresults) - sfail, "probes_not_checked": not_checked,
                            "total_failures": failures},
                "checks": [check_receipt(r) for r in results],
                "supports": [support_receipt(r) for r in sresults],
                "audit_checks": [check_receipt(r) for r in aresults],
                "audit_supports": [support_receipt(r) for r in asup],
                "cross_check_problems": _clean(problems),
                "smoke": _clean({k: smoke.get(k) for k in ("removed_index", "deprecated_index", "unmaintained_index", "engine_ok",
                                                          "engine_total", "problems", "mode")}),
            }
            text = json.dumps(receipt, indent=1, ensure_ascii=False, default=str)
            leaks_in_receipt = leaked_paths(text)
            if leaks_in_receipt:
                print(f"WARNING: {len(leaks_in_receipt)} possible local paths remain in the receipts: {leaks_in_receipt[:3]}", file=sys.stderr)
            with open(a.receipts, "w", encoding="utf-8") as fh:
                fh.write(text + "\n")
            out(f"receipts                : {a.receipts} (sha256 {hashlib.sha256(text.encode('utf-8')).hexdigest()[:16]}...)")
    finally:
        ws.close()
    leaks = leaked_paths("\n".join(lines))
    if leaks:
        print(f"WARNING: {len(leaks)} possible local paths remain in the log: {leaks[:3]}", file=sys.stderr)
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
